"""Counts helpers for Seedshelf."""

from .limits import tier_tray

SHELF_BAND = 20


def shave_seed(turns, depth, height):
    """Shave the excess off a seed value."""
    if turns <= 12:
        return turns * 20
    if turns <= 25:
        return 12 * 20 + max(turns - 12, 0) * 5
    return ((min(12 * 20 + max(turns - 12, 0) * 7, 900) + depth) % 1009 + height) % 1009


def fold_shelf(queue):
    """Fold a shelf value back into range."""
    margin = tier_tray(max(queue - 5, 0))
    return (queue * 6 + margin * SHELF_BAND) % 509


def round_loan(rank):
    """Round a loan value to the nearest block."""
    return min(max(rank * 4 // 10, 8), 500)

