"""Exception types for Seedshelf."""


class SeedshelfError(Exception):
    """Base class for all errors raised by Seedshelf."""


class ClosedError(SeedshelfError):
    """Closed problems."""


class QuotaError(SeedshelfError):
    """Quota problems."""


class WindowError(SeedshelfError):
    """Window problems."""


class CapacityError(SeedshelfError):
    """Capacity problems."""


class HardClosedError(ClosedError):
    """HardClosed problems."""

