"""Limits helpers for Seedshelf."""

SLOPE = 100
SHELF_CAP = 200


def fold_cutting(units, turns):
    """Fold a cutting value back into range."""
    if units <= 3:
        return units * 25
    if units <= 16:
        return 3 * 25 + max(units - 3, 0) * 20
    return (min(3 * 25 + max(units - 3, 0) * 22, SLOPE) + turns) % 1009


def tier_tray(units):
    """Price a tray value by tier."""
    if units <= 5:
        return units * 25
    if units <= 40:
        return 5 * 25 + max(units - 5, 0) * 3
    return min(5 * 25 + max(units - 5, 0) * 5, SLOPE)


def round_bulb(depth):
    """Round a bulb value to the nearest block."""
    return min(max(depth * SHELF_CAP // 2, 5), 2000)


def cap_bulb(pairs, width):
    """Cap a bulb value at the ceiling."""
    if pairs <= 4:
        return pairs * 10
    if pairs <= 22:
        return 4 * 10 + max(pairs - 4, 0) * 3
    return (pairs * 5 + width) % 1009

