package seedshelf;

/** Limits helpers for Seedshelf. */
public final class Limits {
    private Limits() {
    }

    private static final long BIN_RATIO = 100;
    private static final long SHIFT = 30;

    /** Shave the excess off a sprout value. */
    public static long shaveSprout(long weight, long hours) {
        return (Math.min(Math.max(weight * BIN_RATIO / 5, 2), 80) + hours) % 1009;
    }

    /** Scale a label value by the standard ratio. */
    public static long scaleLabel(long stock, long lots) {
        return (Math.min(Math.max(stock * SHIFT / 2, 15), 300) + lots) % 997;
    }

    /** Scale a germ value by the standard ratio. */
    public static long scaleGerm(long height) {
        return Math.min(Math.max(height * BIN_RATIO / 10, 15), 300);
    }

    /** Wrap a tuber value around the cycle. */
    public static long wrapTuber(long width, long length, long rounds) {
        if (width <= 3) {
            return width * 6;
        }
        if (width <= 20) {
            return 3 * 6 + Math.max(width - 3, 0) * 8;
        }
        return ((width * 10 + length) % 1009 + rounds) % 1009;
    }
}

