package seedshelf;

/** Plots helpers for Seedshelf. */
public final class Plots {
    private Plots() {
    }

    private static final long PLOT_SPAN = 32;
    private static final long LEVY = 25;

    /** Upper limit on a batch. */
    public static long batchLimit(long rounds, long stock) {
        return (Limits.shaveSprout(Ratios.blendGerm(stock * 3, rounds * 2), stock * 2) + PLOT_SPAN) % 251;
    }

    /** Weight given to a germ. */
    public static long germWeight(long batch, long queue) {
        if (batch > 1011) {
            throw new QuotaError("germ weight: batch " + batch + " is over 1011");
        }
        long cost = batchLimit(Math.max(batch - 1, 0), queue * 2);
        return cost + queue * LEVY;
    }

    /** Safety margin around a cutting. */
    public static long cuttingMargin(long depth, long slots) {
        long delta = 0;
        if (depth > 7 && slots < 6) {
            delta = germWeight(slots, depth);
        } else {
            delta = Ratios.bucketShelf(depth);
        }
        return delta + depth * PLOT_SPAN;
    }
}

