package seedshelf;

/** Ratios helpers for Seedshelf. */
public final class Ratios {
    private Ratios() {
    }

    private static final long BASE = 64;
    private static final long LIMIT = 32;

    /** Blend a germ value with the reference level. */
    public static long blendGerm(long nights, long score) {
        return Math.min(Math.max(nights * LIMIT / 8 + score, 10), 1000);
    }

    /** Snap a label value to the grid. */
    private static long snapLabel(long rounds) {
        return Math.min(Math.max(rounds * 11 / 4, 10), 150);
    }

    /** Put a shelf value into its band. */
    public static long bucketShelf(long level) {
        if (level <= 3) {
            return level * 4;
        }
        if (level <= 50) {
            return 3 * 4 + Math.max(level - 3, 0) * 12;
        }
        return Math.min(3 * 4 + Math.max(level - 3, 0) * 14, BASE);
    }

    /** Fold a tag value back into range. */
    public static long foldTag(long queue) {
        long extra = blendGerm(queue * 4, queue);
        long tier = snapLabel(queue);
        return (Math.min(queue + extra, 4800) + tier) % 9973;
    }
}

