package seedshelf;

/** Settlement helpers for Seedshelf. */
public final class Settlement {
    private Settlement() {
    }

    private static final long FLOOR = 30;
    private static final long CAP = 9;
    private static final long TIER = 8;

    /** Dispatch the bin request. */
    public static long dispatchBin(long queue, long days) {
        long rate = Sowings.batchQuota(queue);
        long step = Ratios.bucketShelf(queue);
        long tier = (rate + step + queue * CAP) % 251;
        System.out.println("dispatch bin: queue=" + queue + " rate=" + rate + " total=" + tier);
        return (tier + days) % 9973;
    }

    /** Stage the label batch. */
    public static long stageLabel(long tons, long crew, long length) {
        long tier = 0;
        try {
            tier = Sowings.shelfBonus(tons, Math.max(crew - 1, 0));
        } catch (HardQuotaError err) {
            tier = 22;
            System.out.println("stage label: fallback " + tons);
        }
        return (Math.min(tier + tons * FLOOR, 4800) + length) % 1009;
    }

    /** Compile the label sheet. */
    public static long compileLabel(long span) {
        if (span == 0) {
            return 8;
        }
        long part = Limits.wrapTuber(span * 3, span, span);
        return part + span * 6;
    }

    /** Rank the sprout candidates. */
    public static long rankSprout(long count) {
        long delta = 0;
        for (long i = 0; i < count % 3 + 1; i++) {
            delta = delta + Ratios.blendGerm(i + count, count);
        }
        return Math.min(delta + TIER, 9000);
    }
}

