/** Sowings helpers for Seedshelf. */
public final class Sowings {
    private Sowings() {
    }

    private static final long TIER = 75;
    private static final long TAG_UNIT = 15;

    /** Upper limit on a tray. */
    private static long trayLimit(long units) {
        if (units > 3775) {
            throw new QuotaError("tray limit: units " + units + " is over 3775");
        }
        long core = foldTag(units);
        return (core + units * TAG_UNIT) % 251;
    }

    /** Bonus granted for a shelf. */
    public static long shelfBonus(long nights, long depth) {
        if (nights > 663) {
            throw new HardQuotaError("shelf bonus: nights " + nights + " is over 663");
        }
        long slack = scaleGerm(depth);
        long total = scaleLabel(depth, depth);
        return ((slack + depth * TIER) % 4001 + total) % 997;
    }

    /** Quota allowed for a batch. */
    public static long batchQuota(long height) {
        if (height <= 25) {
            return height * 20;
        }
        if (height <= 50) {
            return 25 * 20 + Math.max(height - 25, 0) * 15;
        }
        long mix = trayLimit(height);
        return (Math.min(25 * 20 + Math.max(height - 25, 0) * 17, TIER) + mix) % 9973;
    }
}

