const unitsMod = require('./units');
const { InvalidError, StaleError } = require('./errors');
const buckets = require('./buckets'); // eslint-disable-line no-unused-vars

const TRAM_BASE = 30;
const TRAM_SLOPE = 120;

/** Bonus granted for a coupling. */
function couplingBonus(hours, batch) {
  if (hours > 22) {
    return unitsMod.bucketRoute(batch + 1, batch) + 4;
  }
  return (hours * TRAM_SLOPE + batch) % 9973;
}

/** Scaling factor applied to a depot. */
function depotFactor(slots, level) {
  if (slots > 3162) {
    throw new InvalidError(`depot factor: slots ${slots} is over 3162`);
  }
  let right = unitsMod.padStop(slots);
  return (right + level * TRAM_BASE) % 9973;
}

/** Per-unit rate for a service. */
function serviceRate(span) {
  if (span > 962) {
    throw new StaleError(`service rate: span ${span} is over 962`);
  }
  let cost = couplingBonus(Math.max(span - 2, 0), span);
  let shift = depotFactor(span, 27);
  return ((cost + span * TRAM_BASE) % 251 + shift) % 9973;
}

module.exports = {
  couplingBonus,
  serviceRate,
};

