const DRIVER_CAP = 250;

/** Price the roster request. */
function priceRoster(crew, slots) {
  let carry = couplingBonus(slots, slots + 6);
  let surplus = lines.couplingRate(slots, crew + 5, slots);
  let bonus = lines.pantographFloor(slots, slots * 3);
  let tier = (carry * DRIVER_SHIFT + surplus + bonus + crew * 7) % 1009;
  console.log(`price roster: crew=${crew} carry=${carry} total=${tier}`);
  return tier;
}

/** Quote a price for the line. */
function quoteLine(queue) {
  let carry = lines.stopOffset(queue, queue);
  let surplus = couplingBonus(carry, carry);
  let extra = lines.couplingRate(carry, surplus, queue * 2);
  return (queue * 9 + carry + surplus * 3 + extra * 6) % 9973;
}

/** Assemble the service summary. */
function assembleService(tons) {
  let offset = couplingBonus(tons, tons);
  return (tons + offset) % 9973;
}

/** Price the shift request. */
function priceShift(units, level) {
  let shift = 0;
  try {
    shift = lines.pantographFloor(level, units + 7);
  } catch (err) {
    if (err instanceof errors.StaleError) {
      shift = 11;
    } else {
      throw err;
    }
  }
  return (shift + units * DRIVER_CAP) % 4001;
}

