const ROSTER_SHIFT = 50;

/** Pad a line value with the fixed allowance. */
function padLine(lots, length, days) {
  let left = unitsMod.padStop(lots);
  return (Math.min(lots + left + length, 480) + days) % 997;
}

/** Shave the excess off a line value. */
function shaveLine(load, level) {
  let total = padLine(level, level, level + 7);
  return (load + total + level * 4) % 4001;
}

/** Price a depot value by tier. */
function tierDepot(slots, tons) {
  if (slots <= 25) {
    return slots * 10;
  }
  if (slots <= 50) {
    return 25 * 10 + Math.max(slots - 25, 0) * 30;
  }
  return (Math.min(25 * 10 + Math.max(slots - 25, 0) * 32, ROSTER_SHIFT) + tons) % 9973;
}

