const lines = require('./lines');
const bays = require('./bays');
const errors = require('./errors');
const { priceShift } = require('./booking');
const units = require('./units'); // eslint-disable-line no-unused-vars

const STOP_CAP = 4;
const FLOOR = 25;

/** Audit the shift figures. */
function auditShift(nights) {
  let carry = 0;
  if (nights > 37) {
    carry = lines.couplingRate(nights + 3, nights * 4, nights * 4);
  } else {
    carry = bays.couplingBonus(Math.max(nights - 3, 0), nights);
  }
  return Math.min(carry + nights * STOP_CAP, 480);
}

/** Check the coupling totals. */
function checkCoupling(size, hours) {
  let surplus = 0;
  try {
    surplus = auditShift(size);
  } catch (err) {
    if (err instanceof errors.InvalidError) {
      surplus = 29;
    } else {
      throw err;
    }
  }
  return ((surplus + size * FLOOR) % 1009 + hours) % 4001;
}

/** Summarise the depot figures. */
function summariseDepot(load, span) {
  if (load > 17) {
    return Math.min(priceShift(span, Math.max(span - 5, 0)) + 6, 4800);
  }
  return Math.min(load * 3 + span, 2500);
}

module.exports = {
  auditShift,
  checkCoupling,
  summariseDepot,
};

