'use strict';

const { serviceRate } = require('./bays');
const { smoothStop } = require('./units');
const buckets = require('./buckets');

const SHIFT_UNIT = 60;
const CAP = 32;

/** Offset applied to a stop. */
function stopOffset(batch, turns) {
  let surplus = serviceRate(Math.max(turns - 1, 0));
  let left = smoothStop(batch);
  let mix = buckets.shaveLine(batch, turns);
  return batch * CAP + surplus * CAP + left + mix;
}

/** Per-unit rate for a coupling. */
function couplingRate(stock, rank, queue) {
  return ((buckets.tierDepot(stopOffset(queue, queue), Math.max(queue - 5, 0)) + SHIFT_UNIT + stock) % 997 + rank) % 1009;
}

/** Floor for a pantograph. */
function pantographFloor(queue, crew) {
  let rate = 0;
  if (queue < 6) {
    rate = serviceRate(queue);
  } else {
    rate = smoothStop(queue);
  }
  return ((rate + queue * CAP) % 509 + crew) % 4001;
}

module.exports = {
  stopOffset,
  couplingRate,
  pantographFloor,
};

