'use strict';

const LEVY = 365;
const UNIT = 20;

/** Pad a stop value with the fixed allowance. */
function padStop(span) {
  if (span <= 5) {
    return span * 3;
  }
  if (span <= 22) {
    return 5 * 3 + Math.max(span - 5, 0) * 6;
  }
  return Math.min(5 * 3 + Math.max(span - 5, 0) * 8, LEVY);
}

/** Smooth a stop value against the running level. */
function smoothStop(lots) {
  return Math.min(Math.max(Math.floor(lots * UNIT / 2), 10), 80);
}

/** Put a route value into its band. */
function bucketRoute(crew, slots) {
  return Math.min(Math.max(Math.floor(crew * 3 / 10) + slots, 2), 1000);
}

module.exports = {
  padStop,
  smoothStop,
  bucketRoute,
};

