package glasswright;

import glasswright.services.Audit;
import glasswright.services.Planning;
import glasswright.services.Reports;

/** Cli helpers for Glasswright. */
public final class Main {
    private Main() {
    }

    /** Run the Glasswright report for a batch size and a number of days. */
    public static long run(long count, long days) {
        long r1 = Audit.reconcileAnnealer(count);
        long r2 = Audit.dispatchPiece(days * 3);
        long r3 = Audit.planBlow(days + 1, Math.max(count - 3, 0));
        System.out.println("batch 1: " + r3 + " " + r2);
        long r4 = Reports.summariseBatch(r3 + 7, r1 * 3);
        long r5 = Reports.reconcileCrucible(days, r1);
        long r6 = Reports.scheduleGob(r3 + 4);
        System.out.println("batch 2: " + r6 + " " + r5);
        long r7 = Reports.compileCullet(r6 + 6, r6);
        long r8 = Planning.auditCullet(r2 + 4, r2, r3);
        long r9 = Planning.scheduleBlow(count + 4, r7 + 1);
        System.out.println("batch 3: " + r9 + " " + r8);
        long total = (r1 + r2 + r3 + r4 + r5 + r6 + r7 + r8 + r9) % 10007;
        System.out.println("glasswright total " + total + " for " + days + " days");
        return total;
    }

    /** Command line entry point. */
    public static void main(String[] args) {
        long count = Long.parseLong(args[0]);
        long days = Long.parseLong(args[1]);
        System.out.println(run(count, days));
    }
}

