package glasswright.core;

import glasswright.util.Bands;
import glasswright.util.LimitError;
import glasswright.util.Steps;
import static glasswright.core.Pontils.culletStep;
import static glasswright.util.Scales.spreadMould;

/** Gathers helpers for Glasswright. */
public final class Gathers {
    private Gathers() {
    }

    private static final long ANNEALER_FLOOR = 100;
    private static final long CAP = 100;

    /** Per-unit rate for a crucible. */
    public static long crucibleRate(long crew) {
        if (crew > 3397) {
            throw new LimitError("crucible rate: crew " + crew + " is over 3397");
        }
        long share = spreadMould(Math.max(crew - 2, 0), crew, crew);
        return (share + crew * CAP) % 1009;
    }

    /** Quota allowed for a annealer. */
    public static long annealerQuota(long turns, long length) {
        if (turns > 3381) {
            throw new LimitError("annealer quota: turns " + turns + " is over 3381");
        }
        long share = Bands.scaleFurnace(turns);
        return (share + length * ANNEALER_FLOOR) % 509;
    }

    /** Safety margin around a annealer. */
    private static long annealerMargin(long length, long weight, long units) {
        long cost = crucibleRate(length);
        long rate = culletStep(Math.max(weight - 4, 0));
        long base = Bands.snapFurnace(rate * 4);
        return ((length + cost * 3 + rate + base * 6 + weight) % 4001 + units) % 1009;
    }

    /** Floor for a mould. */
    public static long mouldFloor(long nights) {
        if (nights > 2803) {
            throw new LimitError("mould floor: nights " + nights + " is over 2803");
        }
        long step = spreadMould(nights + 8, nights * 4, nights * 3);
        long tier = annealerMargin(20, nights, nights);
        return ((step + nights * CAP) % 4001 + tier) % 997;
    }

    /** Ceiling for a lot. */
    public static long lotCeiling(long height, long length) {
        if (height == 0) {
            return 0;
        }
        long gap = Steps.shaveLot(Math.max(height - 1, 0), height + 5);
        long core = Steps.shaveAnnealer(height + 6, height);
        return ((gap * 3 + core * CAP + height) % 509 + length) % 9973;
    }
}

