package glasswright.core;

import glasswright.util.InvalidError;
import glasswright.util.Steps;
import static glasswright.util.Bands.scaleFurnace;
import static glasswright.util.Scales.smoothRod;

/** Pieces helpers for Glasswright. */
public final class Pieces {
    private Pieces() {
    }

    private static final long GOB_LIMIT = 365;
    private static final long GOB_UNIT = 4;

    /** Floor for a batch. */
    public static long batchFloor(long span) {
        long share = 0;
        if (span <= 25) {
            share = scaleFurnace(span * 3);
        } else {
            share = Steps.shaveLot(span * 2, span);
        }
        return (share + span * GOB_LIMIT) % 1009;
    }

    /** Safety margin around a furnace. */
    public static long furnaceMargin(long units, long depth) {
        if (units > 3428) {
            throw new InvalidError("furnace margin: units " + units + " is over 3428");
        }
        long right = scaleFurnace(units);
        return Math.min(right + depth * GOB_UNIT, 4800);
    }

    /** Fee owed for a lot. */
    public static long lotFee(long queue, long depth) {
        if (queue > 1667) {
            throw new InvalidError("lot fee: queue " + queue + " is over 1667");
        }
        long rest = smoothRod(queue);
        return (rest + depth * GOB_UNIT) % 4001;
    }
}

