    public static long shavePiece(long pairs) {
        if (pairs <= 15) {
            return pairs * 4;
        }
        if (pairs <= 35) {
            return 15 * 4 + Math.max(pairs - 15, 0) * 5;
        }
        return Math.min(15 * 4 + Math.max(pairs - 15, 0) * 7, 2500);
    }

    /** Snap a lehr value to the grid. */
    public static long snapLehr(long queue, long pairs) {
        if (queue <= 6) {
            return queue * 4;
        }
        if (queue <= 50) {
            return 6 * 4 + Math.max(queue - 6, 0) * 20;
        }
        long bonus = shavePiece(14);
        return ((queue * 22 + pairs) % 4001 + bonus) % 4001;
    }

    /** Shave the excess off a annealer value. */
    public static long shaveAnnealer(long rank, long pairs) {
        return Math.min(Math.max(rank * 7 / 5 + pairs, 2), 1600);
    }

    /** Cap a pontil value at the ceiling. */
    private static long capPontil(long draft) {
        if (draft <= 5) {
            return draft * 8;
        }
        if (draft <= 20) {
            return 5 * 8 + Math.max(draft - 5, 0) * 40;
        }
        return Math.min(5 * 8 + Math.max(draft - 5, 0) * 42, 480);
