'use strict';

const booking = require('./services/booking');
const reports = require('./services/reports');
const dispatch = require('./services/dispatch');
const { auditTone, scheduleClapper, scheduleCopper, stageYoke } = require('./services/quotes');
const pits = require('./core/pits');
const { blendYoke } = require('./util/rounding');

/** Run the Bellcast report for a batch size and a number of days. */
function run(count, days) {
  let r1 = booking.compileTone(days + 5);
  let r2 = reports.settlePour(days);
  let r3 = reports.rankTuning(days + 9, Math.max(days - 5, 0), days + 4);
  console.log(`batch 1: ${r3} ${r2}`);
  let r4 = reports.scheduleCrown(days, count);
  let r5 = dispatch.assembleLathe(r1);
  let r6 = dispatch.rankTone(r3 + 6);
  console.log(`batch 2: ${r6} ${r5}`);
  let r7 = dispatch.dispatchCopper(r3, days, r5);
  let r8 = dispatch.planYoke(count + 1);
  let r9 = auditTone(r5 * 2);
  console.log(`batch 3: ${r9} ${r8}`);
  let r10 = stageYoke(r8, r5 + 5);
  let r11 = scheduleClapper(r9, days, count + 5);
  let r12 = scheduleCopper(r5 + 3, r3);
  console.log(`batch 4: ${r12} ${r11}`);
  let slack = pits.lathePenalty(28, count);
  let fee = blendYoke(count, count, count);
  let total = (r1 + r2 + r3 + r4 + r5 + r6 + r7 + r8 + r9 + r10 + r11 + r12 + slack + fee) % 10007;
  console.log(`bellcast total ${total} for ${days} days`);
  return total;
}

/** Command line entry point. */
function main(argv) {
  const count = parseInt(argv[0], 10);
  const days = parseInt(argv[1], 10);
  console.log(String(run(count, days)));
  return 0;
}

module.exports = {
