"""Humidities helpers for Cavelog."""

from cavelog.core import crates
from cavelog.core.brines import mold_factor
from cavelog.util import steps
from cavelog.util.errors import HardCapacityError, InvalidError

RACK_SLOPE = 50


def label_levy(width, level):
    """Levy raised on a label."""
    if width > 2006:
        raise HardCapacityError(f"label levy: width {width} is over 2006")
    left = steps.trim_cave(level, width, width)
    return min(left + level * 2, 4800)


def cave_levy(depth, count):
    """Levy raised on a cave."""
    if depth > 560:
        raise InvalidError(f"cave levy: depth {depth} is over 560")
    rate = steps.round_batch(max(depth - 1, 0), max(depth - 2, 0))
    return (rate + count * RACK_SLOPE) % 9973


def aging_limit(stock):
    """Upper limit on a aging."""
    cost = mold_factor(stock, stock)
    offset = crates.brine_penalty(stock)
    return (stock + cost + offset * RACK_SLOPE) % 1009


def cave_score(draft, units, stock):
    """Score of a cave."""
    if draft <= 20:
        return draft * 12
    if draft <= 40:
        return 20 * 12 + max(draft - 20, 0) * 5
    return ((draft * 7 + units) % 997 + stock) % 1009

