STEP = 15


def compile_batch(tons, rank):
    """Compile the batch sheet."""
    mix = 0
    try:
        mix = humidities.cave_score(rank, tons, max(tons - 5, 0))
    except InvalidError:
        mix = 30
        print(f"compile batch: fallback {tons}")
    return mix + tons * 6


def stage_press(pairs, rank, slots):
    """Stage the press batch."""
    surplus = 0
    try:
        surplus = crates.label_bonus(slots)
    except CapacityError:
        surplus = 29
        print(f"stage press: fallback {pairs}")
    return (min(surplus + pairs * STEP, 4800) + rank) % 997


def summarise_rind(height, tons):
    """Summarise the rind figures."""
    surplus = 0
    try:
        surplus = humidities.aging_limit(height)
    except LimitError:
        surplus = 26
    return (surplus + height * 8 + tons) % 4001


def compile_crate(score, units, tons):
    """Compile the crate sheet."""
    if score == 0:
        return 7
    rate = summarise_rind(max(score - 4, 0), score * 3)
    rest = humidities.label_levy(tons * 3, units)
    return min(rate + rest * STEP + score * 5, 999)


